CREATE COLUMN TABLE "TEST_AP"."NFN2" ("ObjectCode" NVARCHAR(20) NOT NULL , "UserSign" SMALLINT CS_INT NOT NULL , "SeqCode" SMALLINT CS_INT NOT NULL , "DocSubType" NVARCHAR(2) DEFAULT '--' NOT NULL , PRIMARY KEY ("ObjectCode", "DocSubType", "UserSign", "SeqCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "NFN2_USER" ON "TEST_AP"."NFN2" ( "UserSign" ASC )